import {
  sdk
} from "./chunk-NFEK63OE.mjs";

// src/hooks/api/auth.tsx
import {
  useMutation,
  useQuery
} from "@tanstack/react-query";
var authProvidersQueryKey = ["auth", "providers"];
var useAuthProviders = (options) => {
  const { data, ...rest } = useQuery({
    queryKey: authProvidersQueryKey,
    queryFn: async () => sdk.auth.listProviders("user"),
    staleTime: 5 * 60 * 1e3,
    ...options
  });
  return { ...data, ...rest };
};
var provisionAuthUser = async (provider, token) => {
  await sdk.auth.createUser(provider, {
    Authorization: `Bearer ${token}`
  });
};
var useSignInWithEmailPass = (options) => {
  return useMutation({
    mutationFn: (payload) => sdk.auth.login(
      "user",
      "emailpass",
      payload
    ),
    onSuccess: async (data, variables, context) => {
      options?.onSuccess?.(data, variables, context);
    },
    ...options
  });
};
var useSignUpWithEmailPass = (options) => {
  return useMutation({
    mutationFn: (payload) => sdk.auth.register("user", "emailpass", payload),
    onSuccess: async (data, variables, context) => {
      options?.onSuccess?.(data, variables, context);
    },
    ...options
  });
};
var useResetPasswordForEmailPass = (options) => {
  return useMutation({
    mutationFn: (payload) => sdk.auth.resetPassword("user", "emailpass", {
      identifier: payload.email
    }),
    onSuccess: async (data, variables, context) => {
      options?.onSuccess?.(data, variables, context);
    },
    ...options
  });
};
var useLogout = (options) => {
  return useMutation({
    mutationFn: () => sdk.auth.logout(),
    ...options
  });
};
var useUpdateProviderForEmailPass = (token, options) => {
  return useMutation({
    mutationFn: (payload) => sdk.auth.updateProvider("user", "emailpass", payload, token),
    onSuccess: async (data, variables, context) => {
      options?.onSuccess?.(data, variables, context);
    },
    ...options
  });
};

export {
  useAuthProviders,
  provisionAuthUser,
  useSignInWithEmailPass,
  useSignUpWithEmailPass,
  useResetPasswordForEmailPass,
  useLogout,
  useUpdateProviderForEmailPass
};
